/**
 * KS-1018 — three verification-store reads swallow EVERY DB error with a bare
 * `catch {}` and answer from an in-memory map. A refused connection must now
 * propagate as 503 SERVICE_UNAVAILABLE rather than masquerading as "no such
 * request". The predicate under test is NOT mocked — only the db layer itself.
 *
 * Cells:
 *   🔴 REPRO GET /me/verification — ECONNREFUSED → 503 (was 200 `{ requests: [] }`)
 *   🔴 REPRO POST /verification/:id/review SYSTEM_ADMIN — ECONNREFUSED → 503 (was 404)
 *   CONTROL non-infra DB error still falls through to the in-memory map
 * Added by seat A (KS-1018; the READY covered two of the three sites and no log line):
 *   🔴 REPRO POST /me/verification — ECONNREFUSED on the pending-request read → 503, nothing saved (was 200 + a new PENDING row)
 *   CONTROL POST /me/verification — a non-infra error on that read still falls through (200 PENDING)
 *   🔴 each rethrow logs exactly one `DB <fn> failed` line whose meta is exactly {error, code} (was no log at all)
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import express from 'express';

const SEED_USER_ID = 'aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa';

// NOTE: state MUST be declared AFTER these hoisted blocks — see reference test
// ks1013 for why vitest's hoisting order matters here.
const state = vi.hoisted(() => ({
  caller: { userId: 'aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa', role: 'USER', tenantId: 'tenant-default' },
  users: new Map<string, Record<string, unknown>>(),
}));
const dbQuery = vi.hoisted(() => vi.fn());

vi.mock('../repositories/userRepo', () => {
  const repoMock = {
    getUserById: vi.fn(async (id: string) => state.users.get(id) ?? null),
    getUserByIdPlatformScope: vi.fn(async (id: string) => state.users.get(id) ?? null),
    updateUser: vi.fn(async () => null),
    updateUserPlatformScope: vi.fn(async () => null),
    listUsers: vi.fn(async () => []),
    countUsers: vi.fn(async () => 0),
    listOrganizations: vi.fn(async () => []),
    getOrganizationTenant: vi.fn(async () => ({ tenantId: 'tenant-default' })),
    emailExists: vi.fn(async () => false),
    createUser: vi.fn(async (user: Record<string, unknown>) => user),
    createInvitedStub: vi.fn(async () => ({ user: {}, alreadyExisted: false })),
  };
  return { default: repoMock, __esModule: true, ...repoMock };
});

vi.mock('../middleware/authenticate', () => {
  const injectCaller =
    () => (req: express.Request & { user?: unknown }, _res: express.Response, next: express.NextFunction) => {
      (req as { user: unknown }).user = { ...state.caller };
      next();
    };
  return { authenticate: injectCaller, authenticateAccessOrConnector: injectCaller };
});

vi.mock('../db', () => ({ isDbAvailable: () => true, query: dbQuery }));

vi.mock('../services/session', () => ({ revokeAllUserSessions: vi.fn(async () => 0) }));
vi.mock('../services/password', () => ({
  hashPassword: vi.fn(async () => 'hashed'),
  checkPasswordStrength: vi.fn(() => ({ ok: true })),
  verifyPassword: vi.fn(async () => true),
}));
vi.mock('../utils/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

import { userRoutes } from '../routes/users';
import { errorHandler } from '../middleware/errorHandler';
// KS-1018 (seat A): the logger mock is read back so each rethrow's log line is pinned, not just the status.
import { logger } from '../utils/logger';

// KS-1018 (seat A): POST /me/verification falls through to saveVerificationRequest at base, which writes
// a PENDING row into the route module's in-memory map. Its cells use their own users so that state can
// never reach the GET cells above, which read the map for SEED_USER_ID.
const POST_INFRA_USER_ID = 'bbbbbbbb-2222-4222-8222-bbbbbbbbbbbb';
const POST_CONTROL_USER_ID = 'cccccccc-2222-4222-8222-cccccccccccc';

/** The single `DB <fn> failed` error line, asserted to carry exactly {error, code} (no user id, no stack). */
function expectOneInfraLog(fn: string): void {
  // The logger's overloads type a call as [object]; the route calls it as (message, meta).
  const calls = vi.mocked(logger.error).mock.calls as unknown as Array<[string, Record<string, unknown>]>;
  const lines = calls.filter(([msg]) => msg === `DB ${fn} failed`);
  expect(lines).toHaveLength(1);
  expect(Object.keys(lines[0][1]).sort()).toEqual(['code', 'error']);
}

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  app.use('/', userRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => {
    server = app.listen(0, '127.0.0.1', () => {
      const { port } = server.address() as AddressInfo;
      baseUrl = `http://127.0.0.1:${port}`;
      resolve();
    });
  });
});

afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

beforeEach(() => {
  vi.clearAllMocks();
  state.users.clear();
  state.users.set(SEED_USER_ID, {
    id: SEED_USER_ID,
    email: 'a@tenant-a.example',
    role: 'USER',
    status: 'ACTIVE',
    verificationLevel: 'BASIC',
    tenantId: 'tenant-default',
  });
  state.caller = { userId: SEED_USER_ID, role: 'USER', tenantId: 'tenant-default' };
  // Default to a healthy DB so the control cell's "non-infra failure" branch
  // actually reaches the code under test (the catch).
  dbQuery.mockResolvedValue({ rows: [] });
});

const INFRA_ERROR = Object.assign(new Error('connect ECONNREFUSED 127.0.0.1:5432'), { code: 'ECONNREFUSED' });

describe('KS-1018 — three verification-store reads must rethrow infrastructure errors as SERVICE_UNAVAILABLE', () => {
  it('🔴 KS-1018 — GET /me/verification: a refused DB connection answers 503, not 200 from memory', async () => {
    dbQuery.mockRejectedValue(INFRA_ERROR);
    const res = await fetch(`${baseUrl}/me/verification`);
    expect(res.status).toBe(503);
    const body = (await res.json()) as { error: { code: string } }; // KS-1018 (seat A): typed for an including tsc
    expect(body.error.code).toBe('SERVICE_UNAVAILABLE');
  });

  it('🔴 KS-1018 — POST /verification/:id/review as SYSTEM_ADMIN: a refused DB connection answers 503, not 404', async () => {
    state.caller = { userId: SEED_USER_ID, role: 'SYSTEM_ADMIN', tenantId: 'tenant-default' };
    dbQuery.mockRejectedValue(INFRA_ERROR);
    const res = await fetch(`${baseUrl}/verification/some-id/review`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'approve' }),
    });
    expect(res.status).toBe(503);
    const body = (await res.json()) as { error: { code: string } }; // KS-1018 (seat A): typed for an including tsc
    expect(body.error.code).toBe('SERVICE_UNAVAILABLE');
  });

  it('KS-1018 control — a non-infrastructure DB error still falls through to the in-memory map', async () => {
    // A relation-missing error is NOT an infra failure → should fall through and answer empty.
    dbQuery.mockRejectedValue(Object.assign(new Error('relation does not exist'), { code: '42P01' }));
    const res = await fetch(`${baseUrl}/me/verification`);
    expect(res.status).toBe(200);
    const body = (await res.json()) as { data: { requests: unknown[] } }; // KS-1018 (seat A): typed for an including tsc
    expect(body.data.requests).toEqual([]);
  });

  // KS-1018 (seat A): the third site, findPendingVerificationRequest, had no cell in the READY. Only its
  // SELECT fails, so the fall-through at base is observable: base answered 200 and saved a new PENDING
  // request as if none existed; the fix refuses with 503 before anything is written.
  it('🔴 KS-1018 — POST /me/verification: a refused DB connection on the pending-request read answers 503 and saves nothing', async () => {
    state.users.set(POST_INFRA_USER_ID, { id: POST_INFRA_USER_ID, email: 'b@tenant-a.example', role: 'USER', status: 'ACTIVE', verificationLevel: 'BASIC', tenantId: 'tenant-default' });
    state.caller = { userId: POST_INFRA_USER_ID, role: 'USER', tenantId: 'tenant-default' };
    dbQuery.mockImplementation(async (sql: string) => {
      if (/SELECT[\s\S]*status = 'PENDING'/.test(sql)) throw INFRA_ERROR;
      return { rows: [] };
    });
    const res = await fetch(`${baseUrl}/me/verification`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ targetLevel: 'ENHANCED' }),
    });
    expect(res.status).toBe(503);
    const body = (await res.json()) as { error: { code: string } }; // KS-1018 (seat A): typed for an including tsc
    expect(body.error.code).toBe('SERVICE_UNAVAILABLE');
    const inserts = dbQuery.mock.calls.filter(([sql]) => /INSERT INTO verification_upgrade_requests/.test(sql as string));
    expect(inserts).toHaveLength(0);
    expectOneInfraLog('findPendingVerificationRequest');
  });

  it('KS-1018 control — POST /me/verification: a non-infrastructure error on the pending-request read still falls through', async () => {
    state.users.set(POST_CONTROL_USER_ID, { id: POST_CONTROL_USER_ID, email: 'c@tenant-a.example', role: 'USER', status: 'ACTIVE', verificationLevel: 'BASIC', tenantId: 'tenant-default' });
    state.caller = { userId: POST_CONTROL_USER_ID, role: 'USER', tenantId: 'tenant-default' };
    dbQuery.mockImplementation(async (sql: string) => {
      if (/SELECT[\s\S]*status = 'PENDING'/.test(sql)) throw Object.assign(new Error('relation does not exist'), { code: '42P01' });
      return { rows: [] };
    });
    const res = await fetch(`${baseUrl}/me/verification`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ targetLevel: 'ENHANCED' }),
    });
    expect(res.status).toBe(200);
    const body = (await res.json()) as { data: { status: string } }; // KS-1018 (seat A): typed for an including tsc
    expect(body.data.status).toBe('PENDING');
  });

  // KS-1018 (seat A): each rethrow logs one line whose meta is exactly {error, code}; the READY cells asserted
  // only the status, so a missing log line or a user id / stack added to it would have gone unseen.
  it('KS-1018 — each infrastructure rethrow logs exactly one line carrying only {error, code}', async () => {
    dbQuery.mockRejectedValue(INFRA_ERROR);
    await fetch(`${baseUrl}/me/verification`);
    expectOneInfraLog('listUserVerificationRequests');
    vi.mocked(logger.error).mockClear();
    state.caller = { userId: SEED_USER_ID, role: 'SYSTEM_ADMIN', tenantId: 'tenant-default' };
    await fetch(`${baseUrl}/verification/some-id/review`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'approve' }),
    });
    expectOneInfraLog('getVerificationRequest');
  });
});
